#!/usr/bin/env python3
"""Fight Royale: install 1024px VRMs for Zenith and Nythera.

Standalone installer: both optimized models are embedded in this .py file.
They were optimized with the project's own scripts/shrink_vrm.py.
Zenith was shrunk from the uploaded original; Nythera's already-shrunk VRM
was taken from the uploaded game archive (no destructive second pass).

Run from the web directory:
    python install_zenith_nythera_vrms.py
Or specify the web folder explicitly:
    python install_zenith_nythera_vrms.py --web "C:\\path\\to\\fight-royale\\web"
Check changes without installing:
    python install_zenith_nythera_vrms.py --dry-run

Only updates public/models/{zenith,nythera}.vrm and the two look.vrm
references in src/game/roster.ts. Makes backups when replacing files.
No external Python packages required.
"""
import argparse
import base64
import datetime as dt
import hashlib
import os
from pathlib import Path
import re
import shutil
import struct
import sys
import tempfile
import zlib


def choose_web(explicit):
    candidates = [Path(explicit)] if explicit else [
        Path.cwd(), Path.cwd() / "web",
        Path(__file__).resolve().parent,
        Path(__file__).resolve().parent / "web",
        Path(__file__).resolve().parent.parent / "web",
    ]
    for candidate in candidates:
        root = candidate.expanduser().resolve()
        if (root / "src" / "game" / "roster.ts").is_file():
            return root
    checked = "\n  ".join(str(x) for x in candidates)
    raise FileNotFoundError(
        "Cannot locate the Fight Royale web directory. Checked:\n  " + checked +
        '\nUse --web "C:\\...\\fight-royale\\web" to specify it.'
    )


def patch_roster(source):
    entry_rx = re.compile(r"(?m)^\s*\{\s*id\s*:\s*['\"]([a-zA-Z0-9_-]+)['\"]")
    entries = list(entry_rx.finditer(source))
    edits = []
    results = {}
    for name in ("zenith", "nythera"):
        selected = [(i, entry) for i, entry in enumerate(entries) if entry.group(1) == name]
        if len(selected) != 1:
            raise ValueError(f"Expected exactly one roster entry for {name}, found {len(selected)}. No files changed.")
        i, entry = selected[0]
        end = entries[i + 1].start() if i + 1 < len(entries) else len(source)
        section = source[entry.start():end]
        m = re.search(r"\blook\s*:\s*\{[\s\S]*?\bvrm\s*:\s*(['\"])([^'\"]+)\1", section)
        if not m:
            raise ValueError(f"Cannot find look.vrm inside the {name} roster entry. No files changed.")
        results[name] = m.group(2)
        a = entry.start() + m.start(2)
        b = entry.start() + m.end(2)
        edits.append((a, b, name))
    for a, b, replacement in sorted(edits, reverse=True):
        source = source[:a] + replacement + source[b:]
    return source, results


def decode_model(name):
    spec = PAYLOAD[name]
    encoded = "".join(spec["blob"].split())
    content = zlib.decompress(base64.b85decode(encoded))
    if hashlib.sha256(content).hexdigest() != spec["sha256"]:
        raise ValueError(f"Embedded {name}.vrm failed SHA-256 verification")
    if len(content) < 32 or struct.unpack_from("<I", content, 0)[0] != 0x46546C67:
        raise ValueError(f"Embedded {name}.vrm is not a GLB/VRM file")
    if struct.unpack_from("<I", content, 8)[0] != len(content):
        raise ValueError(f"Embedded {name}.vrm has an invalid declared length")
    return content


def replace_atomically(path, data):
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, tmp = tempfile.mkstemp(dir=path.parent, prefix=".vrm_install_", suffix=".tmp")
    try:
        with os.fdopen(fd, "wb") as f:
            f.write(data)
        os.replace(tmp, path)
    finally:
        if os.path.exists(tmp):
            os.unlink(tmp)


def backup(path, stamp):
    target = path.with_name(path.name + f".before_vrm_install_{stamp}.bak")
    counter = 1
    while target.exists():
        target = path.with_name(path.name + f".before_vrm_install_{stamp}_{counter}.bak")
        counter += 1
    shutil.copy2(path, target)
    print(f"  backup: {target.name}")


def main():
    parser = argparse.ArgumentParser(description="Install optimized Zenith + Nythera VRMs and update roster")
    parser.add_argument("--web", metavar="DIRECTORY", help="path to the Fight Royale web folder")
    parser.add_argument("--dry-run", action="store_true", help="show changes without writing files")
    args = parser.parse_args()

    root = choose_web(args.web)
    roster_path = root / "src" / "game" / "roster.ts"
    original_roster = roster_path.read_text(encoding="utf-8-sig")
    new_roster, old_look = patch_roster(original_roster)  # validate before writing

    print(f"Fight Royale web folder: {root}")
    print("Roster model references:")
    for name, current in old_look.items():
        print(f"  {name}: {current} -> {name}" + (" (already set)" if current == name else ""))

    models = {name: decode_model(name) for name in ("zenith", "nythera")}
    stamp = dt.datetime.now().strftime("%Y%m%d_%H%M%S")
    for name, data in models.items():
        destination = root / "public" / "models" / f"{name}.vrm"
        current_matches = destination.exists() and hashlib.sha256(destination.read_bytes()).digest() == hashlib.sha256(data).digest()
        if current_matches:
            print(f"  {name}.vrm: already correct ({len(data)/1_000_000:.2f} MB)")
            continue
        print(f"  {name}.vrm: {'would install' if args.dry_run else 'installing'} ({len(data)/1_000_000:.2f} MB)")
        if not args.dry_run:
            if destination.exists():
                backup(destination, stamp)
            replace_atomically(destination, data)

    if new_roster != original_roster:
        if args.dry_run:
            print("  roster.ts: would update the two VRM references")
        else:
            backup(roster_path, stamp)
            replace_atomically(roster_path, new_roster.encode("utf-8"))
            print("  roster.ts: updated")
    else:
        print("  roster.ts: already correct")

    if args.dry_run:
        print("DRY RUN finished: no files changed.")
    else:
        print("\nSUCCESS: Zenith and Nythera now use their own optimized VRMs.")
        print("Start or restart your dev server with: npm run dev")
        print("Then verify the select screen, weapon grip, and animations.")
        print("Optional verification: npx tsc --noEmit -p .")


